{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "The eligibility framework was specified as follows. Population: women undergoing outpatient or office-based blind endometrial biopsy or endometrial sampling for any clinical indication. Intervention: peri-procedural analgesic, anesthetic, or pain-control strategies intended to reduce pain before or during biopsy or sampling. Comparator: placebo, normal saline, placebo gel, distilled water, or another credible inert control for the primary quantitative analysis; inert controls were defined as matched controls without intended analgesic pharmacologic activity. ... Outcomes: the primary outcome was pain during biopsy or sampling on a 0-10 compatible scale; secondary or supplementary outcomes included highpain thresholds, pain at other procedure-related timepoints, additional analgesia, satisfaction or willingness to repeat biopsy, procedure failure, and adverse events. Study design: randomized controlled trials were eligible for efficacy synthesis, whereas conference abstracts, registry entries, and secondary reports were used for citation ARTICLE IN PRESS mapping, boundary adjudication, or publication-bias assessment unless sufficient arm-level outcome data were available.",
      "reason": "Provides detailed eligibility criteria using population, intervention, comparator (inert controls), outcomes (including follow-up/output time framing as pain during biopsy/sampling), and eligible study design(s)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No explicit eligibility criteria are reported for report characteristics such as dissemination year, language, or publication/report status (e.g., restrictions or lack thereof)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The evidence describes exclusion reasons (e.g., non-inert comparisons, inseparable procedures, lack of separable blind pain data, non-extractable outcome formats), but it does not clearly distinguish exclusion because outcomes were not measured versus exclusion because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "To avoid mixing clinically different comparisons, we organized the evidence into three tiers. Tier 1 was the prespecified primary meta-analysis. It included inert-controlled randomized comparisons with extractable intra-procedural means and standard deviations. Tier 2 comprised sensitivity analyses that tested analytic or clinical boundaries. These included balanced-background ibuprofen designs, in which both randomized groups received ibuprofen and the randomized contrast assessed the added topical or local intervention. Tier 2 also included the analysis excluding the single systemic-only COX-2 inhibitor trial. Tier 3 comprised narrative or tabulated contextual evidence. This tier included medianonly, binary-only, ordinal-only, active-comparator, nonpharmacologic, cervical-preparation, co-intervention, suction/Vabra, registry-only, or mixed-procedure records. We applied this hierarchy before interpreting the pooled estimate.",
      "reason": "Specifies how studies/comparisons were grouped for syntheses (three tiers) and what each tier included (primary inert-controlled comparisons; defined sensitivity analyses; narrative/tabulated contextual evidence)."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_30",
      "quote": "Several eligible or potentially relevant studies were not included in the primary analysis because they did not meet the prespecified extractability or estimand criteria.... Trials reporting only medians and ranges were not converted into means and standard deviations for the main result because such conversion would require distributional assumptions. ... Siddle 1983 and Kozman 2001 involved Vabra or suction-curettage sampling and were retained as boundary/contextual evidence rather than primary blind EMB evidence. ... These decisions reduce apparent inclusiveness but improve interpretability. The primary analysis",
      "reason": "Provides rationales for notable eligibility restrictions/exclusions for the primary quantitative synthesis (e.g., extractability/estimand criteria, avoiding conversions requiring assumptions, boundary/contextual treatment of non-primary sampling settings)."
    }
  ],
  "confidence": 78
}

